command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: SCHLIMMER KATER (Ausführung)
// ==========================================

(async () => {
    // --- 1. FRAMEWORK LADEN ---
    const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) { await fwMacro.execute(); }

    const DSK_FW = globalThis.DSK || DSK;
    if (typeof DSK_FW === "undefined") return ui.notifications.error("Luna sagt 🌙: Framework fehlt!");

    const gabenName = "Schlimmer Kater";
    const ahne = "Aphasma";
    const finalEffektName = `${gabenName} (${ahne})`;
    const iconBild = DSK_FW.Symbol(ahne);

    if (DSK_FW.EffektEnde && !globalThis._dskAphasmaKaterRegistered) {
        globalThis._dskAphasmaKaterRegistered = true;
        DSK_FW.EffektEnde.Register("aphasmaKater", finalEffektName, "Die Nachwirkungen des Katers sind verflogen. Der Verstand ist wieder klar, der Schmerz lässt nach.");
    }

    const getOwners = (act) => Object.entries(act?.ownership || {}).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);

    // --- 2. CASTER & SEINEN TOKEN ERMITTELN ---
    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!casterActor) casterActor = game.actors.find(a => a.getFlag("world", "letzteGabenQS") !== undefined);
    if (!casterActor) {
        for (let t of canvas.tokens.placeables) {
            if (t.actor && t.actor.getFlag("world", "letzteGabenQS") !== undefined) { casterActor = t.actor; break; }
        }
    }
    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");

    let casterToken = casterActor.getActiveTokens()[0] || canvas.tokens.controlled[0];
    if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Der Wirkende braucht einen Token auf der Szene für die Entfernungsberechnung!");

    const qsWert = Number(casterActor.getFlag("world", "letzteGabenQS") || 1);
    const alteMessageId = casterActor.getFlag("world", "letzteGabenMessageId");
    let whisperTargets = [...new Set([...game.users.filter(u => u.isGM).map(u => u.id), ...getOwners(casterActor)])].filter(id => game.users.get(id));

    // --- 3. FUNKTION FÜR FEHLERMELDUNGEN ---
    const sendError = async (grund) => {
        const infoHtml = `
            <div style="font-family: 'Signika', sans-serif;">
                <div class="dskbox1">
                    <p style="display:flex; gap:8px; align-items:center; margin:0;">
                        <img src="${iconBild}" style="width:28px; border:none; background:transparent;">
                        <b style="font-size: 1.05em;">Information</b>
                    </p>
                    <p style="font-weight:bold; margin-top:6px; margin-bottom:0;">${finalEffektName}</p>
                </div>
                <div class="dskbox2" style="margin-top:10px; text-align: center;">
                    <p style="margin-bottom: 8px; color: #8b0000;"><b>Fehlschlag!</b></p>
                    <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                    <p style="margin-bottom: 8px;">${grund}</p>
                </div>
            </div>
        `;
        await ChatMessage.create({ whisper: whisperTargets, speaker: { alias: "System" }, content: infoHtml });
    };

    // --- 4. ZIEL ERMITTELN & PRÜFEN ---
    const targets = Array.from(game.user.targets);
    if (targets.length === 0) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst ein Ziel (Target) aus!");

    const targetToken = targets[0];
    const targetActor = targetToken.actor;
    const targetName = targetToken.name;

    // 4a. Distanz prüfen (Maximal 8 Schritt)
    const distanz = Math.round(DSK_FW.Geometrie.Distanz(casterToken, targetToken) * 10) / 10;
    if (distanz > 8) {
        return sendError(`<b>${targetName}</b> ist zu weit entfernt (${distanz} Schritt). Die Gabe reicht maximal 8 Schritt weit.`);
    }

    // 4b. Wesen prüfen (Muss ein Mensch sein)
    const istMensch = DSK_FW.Wesen.match(targetActor, ["mensch", "menschen"]);
    if (!istMensch) {
        return sendError(`<b>${targetName}</b> ist kein Mensch. Diese Gabe wirkt ausschließlich auf menschliche Geister.`);
    }

    // --- 5. BERECHNUNGEN (ERFOLG) ---
    await casterActor.unsetFlag("world", "letzteGabenQS");
    await casterActor.unsetFlag("world", "letzteGabenMessageId");

    let alterEffekt = targetActor.effects.find(e => (e.name || e.label) === finalEffektName);
    if (alterEffekt) await alterEffekt.delete();

    // Foundry Zeit: 1 Stunde = 3600 Sekunden
    const dauerSekunden = qsWert * 3600;

    await targetActor.createEmbeddedDocuments("ActiveEffect", [{
        name: finalEffektName,
        icon: iconBild,
        img: iconBild,
        duration: { seconds: dauerSekunden },
        description: `Erwacht nach dem nächsten Schlaf mit einem grauenhaften Kater. Erhält ${qsWert} Stufen Schmerz und hat nur bruchstückhafte Erinnerungen an die ${qsWert} Stunden vor dem Zubettgehen.`,
        changes: [{ 
            key: "system.status.inpain", 
            mode: 2, 
            value: qsWert, 
            priority: 20 
        }],
        flags: { dsk: { ahne: ahne } }
    }]);

    // --- 6. CHAT NACHRICHT GENERIEREN ---
    const casterName = DSK_FW.ResolveTokenName(casterActor);
    const thinStyle = 'style="font-weight: 300; font-size: 0.9em; opacity: 0.8;"';

    const successContent = `
        <div style="font-family: 'Signika', sans-serif;">
            ${DSK_FW.UI.Header(finalEffektName, iconBild)}
            <div class="dskbox2" style="margin-top:10px;">
                <p><b>${casterName}</b> verwebt unsichtbare Magie im Geist von <b>${targetName}</b>.</p>
                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                <p style="margin-bottom: 8px;">
                    Wenn das Ziel das nächste Mal schläft, erwacht es mit einem grauenhaften Kater. 
                </p>
                <ul class="dsklist" style="margin-bottom: 8px;">
                    <li>Erleidet <b>${qsWert} Stufen Schmerz</b> nach dem Aufwachen.</li>
                    <li>Erinnert sich nur nebelhaft an die <b>${qsWert} Stunden</b> vor dem Schlafengehen.</li>
                </ul>
                <div style="background:rgba(0,0,0,0.05); border:1px solid #a89f91; padding:6px; border-radius:3px; margin-bottom: 8px; font-size: 0.9em; text-align:center;">
                    <i><b>Hinweis für den GM:</b> Der Effekt und der Schmerz sind mechanisch bereits auf dem Ziel-Bogen hinterlegt. Erzählerisch treten sie jedoch erst <b>nach dem nächsten Schlafen</b> ein!</i>
                </div>
                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                <p style="text-align:center; font-weight:bold;">Wirkungsdauer:<br>${qsWert} Stunden <span ${thinStyle}>(${qsWert} QS)</span></p>
            </div>
        </div>
    `;

    let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
    if (msg) {
        await msg.update({ content: successContent });
    } else {
        await ChatMessage.create({ content: successContent, speaker: { alias: "System" } });
    }
})();
